const cryptoResult = $input.first().json;
const body = $('01 - Receber Evento LAB').first().json.body;

// Resposta controlada para contratos rejeitados.
function reject(reason) {
  return [{
    json: {
      schema_version: '1.0',
      environment: 'LAB',
      processor: 'N8N_RUNTIME_REPORT_RECEIVER',
      transport_status: 'REJECTED_RUNTIME_REPORT',
      integrity_status: 'REJECTED',
      reason_code: reason,
      html_sha256_verified: false,
      human_review_completed: false,
      operational_dispatch_allowed: false,
      notification_sent: false,
      test_only: true
    }
  }];
}

// 1. Validacao da estrutura.
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return reject('INVALID_PAYLOAD');
}

// 2. Contrato esperado.
const expected = {
  schema_version: '1.0',
  environment: 'LAB',
  processor: 'LOCAL_RUNTIME_AI_REPORT',
  source_event_id: 'LAB-0001',
  historical_queue_id: 12,
  historical_status: 'SKIPPED',
  current_queue_id: 13,
  execution_mode: 'LOCAL_OLLAMA',
  report_status: 'AWAITING_HUMAN_REVIEW',
  human_review_required: true,
  human_review_completed: false,
  verified_against_database: false,
  persistence_status: 'NOT_ATTEMPTED',
  operational_dispatch_allowed: false,
  notification_sent: false,
  test_only: true
};

for (const [key, value] of Object.entries(expected)) {
  if (body[key] !== value) {
    return reject('INVALID_CONTRACT');
  }
}

// 3. Validacao do HTML.
if (
  typeof body.html !== 'string' ||
  body.html.length < 100 ||
  body.html.length > 100000 ||
  !body.html.startsWith('<!DOCTYPE html>') ||
  !body.html.includes('LAB-0001') ||
  !body.html.includes('OLLAMA LOCAL - ANALISE REAL') ||
  !body.html.includes('REVISAO HUMANA OBRIGATORIA')
) {
  return reject('INVALID_HTML');
}

// 4. Comparacao das assinaturas.
const declared = body.html_sha256;
const computed = cryptoResult.html_sha256_computed;

const pattern = /^[a-fA-F0-9]{64}$/;

if (
  typeof declared !== 'string' ||
  !pattern.test(declared) ||
  typeof computed !== 'string' ||
  !pattern.test(computed)
) {
  return reject('INVALID_SHA256');
}

if (declared.toLowerCase() !== computed.toLowerCase()) {
  return reject('HASH_MISMATCH');
}

// 5. Somente o contrato integro recebe aprovacao.
return [{
  json: {
    schema_version: '1.0',
    environment: 'LAB',
    processor: 'N8N_RUNTIME_REPORT_RECEIVER',

    transport_status: 'ACCEPTED_RUNTIME_REPORT',
    integrity_status: 'HASH_VERIFIED_IN_N8N',

    source_event_id: body.source_event_id,
    historical_queue_id: 12,
    historical_status: 'SKIPPED',
    current_queue_id: 13,

    execution_mode: 'LOCAL_OLLAMA',
    report_status: 'AWAITING_HUMAN_REVIEW',

    html_received: true,
    html_sha256_verified: true,
    html_sha256_computed: computed.toLowerCase(),

    human_review_required: true,
    human_review_completed: false,
    operational_dispatch_allowed: false,
    notification_sent: false,
    test_only: true
  }
}];
